    private int splitLoop(String s) {
        int i = 0;
        while(i < s.length() && s.charAt(i) == s.charAt(s.length()-1)) i++;
        return i;
    }

    private int splitRemoveCharLoop(char remove_char, int index){
        while(index >= 0 && s.charAt(index) == remove_char) index--;
        return index + 1; // Return the next position after removing all characters
