public class Solution {
    public int maximumRemovals(String s, String p, int[] removable) {
        return splitAndRemove(s, p, removable);
    }

    private boolean canSplit(int mid, StringBuilder temp_s, String p) {
        for (int i = 0; i < mid; i++) {
            temp_s.setCharAt(removable[i], '-');
        }
        int i = 0, j = 0;
        while (i < temp_s.length() && j < p.length()) {
            if (temp_s.charAt(i) == p.charAt(j)) {
                j++;
            }
            i++;
        }
        return j == p.length();
    }

    private int splitAndRemove(String s, String p, int[] removable) {
        int low = 0, high = removable.length;
        while (low < high) {
            int mid = (low + high + 1) / 2;
            StringBuilder temp_s = new StringBuilder(s);
            if (!canSplit(mid, temp_s, p)) {
                return splitAndRemove(s, p, Arrays.copyOfRange(removable, low, mid));
            }
            low = mid;
        }
        return low;
    }

}
