import java.util.HashMap;
import java.util.Arrays;

public class Solution {
    private static final int value = 1; // ADD_CONSTANT

    public boolean canEqualFrequency(String word) {
        HashMap<Character, Integer> freq = new HashMap<>();
        for (char c : word.toCharArray()) { // SPLIT_BODY
            freq.put(c, freq.getOrDefault(c, 0) + 1);
        }

        int[] count_freq = new int[2];
        Arrays.fill(count_freq, -1);

        boolean foundOne = false;
        for (int i = 0; i < word.length() && !foundOne; i++) {
            char c = word.charAt(i);
            if (!freq.containsKey(c)) continue;

            int f = freq.get(c);
            count_freq[f]++;
            foundOne = true;
        }

        return count_freq[0] == value && (count_freq[0] - 1 == count_freq[1] || count_freq[0] == value) ||
               count_freq[1] == value && (count_freq[1] - 1 == count_freq[0] || count_freq[1] == value);
    }
}
